class AnalysisError(ValueError):
    """Invalid settings or insufficient data for a valid result."""


def utc_now() -> str:
    return datetime.now(timezone.utc).isoformat()


def environment_versions() -> dict:
    result = {"application": APP_VERSION, "python": platform.python_version()}
    for name in ("numpy", "pandas", "scipy", "matplotlib", "PySide6", "pyproj"):
        try:
            result[name] = importlib.metadata.version(name)
        except importlib.metadata.PackageNotFoundError:
            result[name] = "not installed"
    return result


@dataclass
class FilterSpec:
    method: str = "none"
    alpha: float = 0.3
    window: int = 5
    polyorder: int = 2

    def validate(self) -> None:
        if self.method not in {"none", "exponential", "savgol", "moving_average"}:
            raise AnalysisError("Unknown filter.")
        if self.method == "exponential" and not (0 < self.alpha <= 1):
            raise AnalysisError("Alpha must be greater than 0 and less than or equal to 1.")
        if self.method in {"savgol", "moving_average"}:
            if self.window < 3 or self.window % 2 != 1:
                raise AnalysisError("The filter window must be odd and at least 3 samples long.")
        if self.method == "savgol" and not (0 <= self.polyorder < self.window):
            raise AnalysisError("The polynomial order must be smaller than the filter window.")


@dataclass
class AnalysisSettings:
    numerator: str = ""
    denominator: str = ""
    marker: str | None = None
    longitude: str | None = None
    latitude: str | None = None
    numerator_filter: FilterSpec = field(default_factory=FilterSpec)
    denominator_filter: FilterSpec = field(default_factory=FilterSpec)
    optimize_shift: bool = True
    max_shift: int = 5
    marker_limit: float = 10.0
    r2_limit: float = 0.7
    window_width: int = 120
    window_step: int = 1
    min_valid_fraction: float = 0.8

    @classmethod
    def from_dict(cls, payload: dict) -> AnalysisSettings:
        values = dict(payload)
        for key in ("numerator_filter", "denominator_filter"):
            values[key] = FilterSpec(**values.get(key, {}))
        return cls(**values)

    def validate(self, dataset: Dataset) -> None:
        columns = dataset.frame.columns[1:]
        if self.numerator not in columns or self.denominator not in columns:
            raise AnalysisError("Select two channels available in the dataset.")
        if self.numerator == self.denominator:
            raise AnalysisError("Numerator and denominator must be different channels.")
        for column in (self.marker, self.longitude, self.latitude):
            if column is not None and column not in columns:
                raise AnalysisError(f"Channel {column!r} is not present in the dataset.")
        if self.longitude and self.latitude and self.longitude == self.latitude:
            raise AnalysisError("Longitude and latitude must be different channels.")
        if not (0 <= self.max_shift <= 1000):
            raise AnalysisError("Maximum shift must be between 0 and 1000 samples.")
        if not (0 <= self.r2_limit <= 1):
            raise AnalysisError("The R² threshold must be between 0 and 1.")
        if self.window_width < 3 or self.window_step < 1:
            raise AnalysisError("The window must contain at least 3 samples and the step must be at least 1.")
        if not (0 < self.min_valid_fraction <= 1):
            raise AnalysisError("The minimum valid-pair fraction must be greater than 0 and at most 1.")
        if not math.isfinite(self.marker_limit):
            raise AnalysisError("The marker threshold must be finite.")
        self.numerator_filter.validate()
        self.denominator_filter.validate()


@dataclass
class Dataset:
    name: str
    frame: pd.DataFrame
    source_path: str = ""
    source_sha256: str = ""
    id: str = field(default_factory=lambda: uuid.uuid4().hex)
    import_options: dict = field(default_factory=dict)
    derived_channels: list = field(default_factory=list)

    @property
    def times(self) -> pd.Series:
        return self.frame.iloc[:, 0]

    def sampling_seconds(self) -> float | None:
        """Return the interval only for regular timestamps, without compressing gaps."""
        if not pd.api.types.is_datetime64_any_dtype(self.times.dtype) or len(self.times) < 2:
            return None
        deltas = np.diff(self.times.astype("int64").to_numpy()) / 1e9
        if not np.isfinite(deltas).all() or (deltas <= 0).any():
            return None
        median = float(np.median(deltas))
        return median if np.allclose(deltas, median, rtol=1e-3, atol=1e-6) else None


def load_datasets(path: str | Path, separator: str = ";", decimal: str = ".",
                  parse_time: bool = True, time_format: str = "%Y-%m-%d %H:%M:%S",
                  split_seconds: float | None = None) -> list[Dataset]:
    source = Path(path)
    raw = source.read_bytes()
    options = dict(separator=separator, decimal=decimal, parse_time=parse_time,
                   time_format=time_format, split_seconds=split_seconds)
    frame = pd.read_csv(io.BytesIO(raw), sep=separator, decimal=decimal, encoding="utf-8-sig")
    if len(frame) < 3 or frame.shape[1] < 3:
        raise AnalysisError("At least three rows and three columns are required: time and two channels.")
    frame.columns = [str(column).strip() for column in frame.columns]
    if frame.columns.duplicated().any():
        raise AnalysisError("Column names must be unique.")
    if parse_time:
        times = pd.to_datetime(frame.iloc[:, 0], format=time_format or "mixed", errors="raise")
        if times.isna().any() or not times.is_monotonic_increasing or times.duplicated().any():
            raise AnalysisError("Timestamps must be valid, increasing and unique.")
        frame[frame.columns[0]] = times
    for column in frame.columns[1:]:
        frame[column] = pd.to_numeric(frame[column], errors="coerce").astype(float)
        frame[column] = frame[column].replace([np.inf, -np.inf], np.nan)
    cuts = [0]
    if split_seconds is not None:
        if not parse_time or split_seconds <= 0:
            raise AnalysisError("Splitting requires timestamps and a positive threshold in seconds.")
        differences = frame.iloc[:, 0].diff().dt.total_seconds().to_numpy()
        cuts.extend(np.flatnonzero(differences > split_seconds).tolist())
    cuts.append(len(frame))
    digest = hashlib.sha256(raw).hexdigest()
    result = []
    for number, (start, stop) in enumerate(zip(cuts[:-1], cuts[1:]), 1):
        part = frame.iloc[start:stop].reset_index(drop=True).copy()
        label = source.name
        if len(cuts) > 2:
            label += f" · segment {number} · {part.iloc[0, 0]}"
        result.append(Dataset(label, part, str(source.resolve()), digest,
                              import_options=dict(options, source_row_start=start, source_row_stop=stop)))
    return result


def finite_runs(values: np.ndarray):
    mask = np.isfinite(values)
    switches = np.diff(np.r_[False, mask, False].astype(np.int8))
    return zip(np.flatnonzero(switches == 1), np.flatnonzero(switches == -1))


def apply_filter(values: np.ndarray, spec: FilterSpec) -> np.ndarray:
    """Filter each finite run separately; do not interpolate or bridge NaN gaps."""
    spec.validate()
    values = np.asarray(values, dtype=float)
    if spec.method == "none":
        return np.where(np.isfinite(values), values, np.nan)
    output = np.full(values.shape, np.nan)
    for start, stop in finite_runs(values):
        run = values[start:stop]
        if spec.method == "exponential":
            output[start:stop] = pd.Series(run).ewm(alpha=spec.alpha, adjust=True).mean().to_numpy()
        elif len(run) >= spec.window:
            if spec.method == "savgol":
                output[start:stop] = signal.savgol_filter(run, spec.window, spec.polyorder, mode="interp")
            else:
                output[start:stop] = pd.Series(run).rolling(
                    spec.window, center=True, min_periods=spec.window).mean().to_numpy()
    return output


@dataclass
class PreparedSignals:
    numerator: np.ndarray
    denominator: np.ndarray
    sampling_seconds: float | None = None


def prepare_signals(dataset: Dataset, settings: AnalysisSettings) -> PreparedSignals:
    settings.validate(dataset)
    return PreparedSignals(
        apply_filter(dataset.frame[settings.numerator].to_numpy(float), settings.numerator_filter),
        apply_filter(dataset.frame[settings.denominator].to_numpy(float), settings.denominator_filter),
        dataset.sampling_seconds())


@dataclass
class FitResult:
    record: dict
    numerator_indices: np.ndarray
    denominator_indices: np.ndarray
    numerator_values: np.ndarray
    denominator_values: np.ndarray


def _paired(prepared: PreparedSignals, indices: np.ndarray, shift: int):
    other = indices + shift
    valid = (other >= 0) & (other < len(prepared.denominator))
    ni, di = indices[valid], other[valid]
    y, x = prepared.numerator[ni], prepared.denominator[di]
    finite = np.isfinite(y) & np.isfinite(x)
    return ni[finite], di[finite], y[finite], x[finite]


def _correlation(x: np.ndarray, y: np.ndarray) -> float | None:
    if len(x) < 3:
        return None
    dx, dy = x - x.mean(), y - y.mean()
    xx, yy = float(dx @ dx), float(dy @ dy)
    if xx <= 0 or yy <= 0:
        return None
    return float(np.clip((dx @ dy) / math.sqrt(xx * yy), -1, 1))


def _finite_stat(dataset: Dataset, column: str | None, indices: np.ndarray,
                 operation: str = "mean") -> float | None:
    if not column:
        return None
    values = dataset.frame[column].to_numpy(float)[indices]
    values = values[np.isfinite(values)]
    if not len(values):
        return None
    return float(values.max() if operation == "max" else values.mean())


def fit_interval(dataset: Dataset, settings: AnalysisSettings, start: int, end: int,
                 prepared: PreparedSignals | None = None, mode: str = "manual",
                 should_cancel: Callable[[], bool] = lambda: False) -> FitResult:
    """Inclusive interval; shift s pairs numerator[i] with denominator[i+s]."""
    if prepared is None:
        prepared = prepare_signals(dataset, settings)
    start, end = int(start), int(end)
    if not (0 <= start <= end < len(dataset.frame)):
        raise AnalysisError("The selected interval is outside the dataset.")
    indices = np.arange(start, end + 1)
    required = max(3, math.ceil(len(indices) * settings.min_valid_fraction))
    max_shift = settings.max_shift if settings.optimize_shift else 0
    # Common support makes correlations at different shifts comparable.
    # Exclude only edges that do not allow every candidate pairing.
    support = indices[(indices >= max_shift) & (indices < len(dataset.frame) - max_shift)]
    if len(support) < required:
        raise AnalysisError("Too few valid samples: reduce the shift/filter or expand the interval.")
    # Tie-breaking preference: zero, -1, +1, -2, +2, ...
    shifts = [0] + [s for magnitude in range(1, max_shift + 1) for s in (-magnitude, magnitude)]
    best = None
    for shift in shifts:
        if should_cancel():
            raise InterruptedError("Analysis cancelled.")
        ni, di, y, x = _paired(prepared, support, shift)
        if len(x) < required:
            continue
        correlation = _correlation(x, y)
        if correlation is not None and (best is None or correlation > best[0] + 1e-12):
            best = (correlation, shift, ni, di, y, x)
    if best is None:
        raise AnalysisError("No valid regression: missing values or constant channels.")
    correlation, shift, ni, di, y, x = best
    regression = stats.linregress(x, y)
    ci95 = float(stats.t.ppf(0.975, len(x) - 2) * regression.stderr)
    midpoint = int(ni[len(ni) // 2])
    step = prepared.sampling_seconds
    record = {
        "result_id": uuid.uuid4().hex, "mode": mode, "dataset_id": dataset.id,
        "dataset": dataset.name, "source_path": dataset.source_path,
        "source_sha256": dataset.source_sha256, "calculated_at": utc_now(),
        "numerator": settings.numerator, "denominator": settings.denominator,
        "marker": settings.marker, "selection_start": start, "selection_end": end,
        "first_sample": int(ni[0]), "last_sample": int(ni[-1]), "index": midpoint,
        "time": str(dataset.times.iloc[midpoint]),
        "start_time": str(dataset.times.iloc[int(ni[0])]),
        "end_time": str(dataset.times.iloc[int(ni[-1])]),
        "ratio": float(regression.slope), "intercept": float(regression.intercept),
        "r": float(regression.rvalue), "r_squared": float(regression.rvalue ** 2),
        "p_value": float(regression.pvalue), "slope_stderr": float(regression.stderr),
        "slope_ci95_halfwidth": ci95, "n_samples": int(len(x)),
        "ratio_ci95_lower": float(regression.slope - ci95),
        "ratio_ci95_upper": float(regression.slope + ci95),
        "ci95_method": "ols_student_t",
        "shift_samples": int(shift), "shift_seconds": shift * step if step is not None else None,
        "max_numerator": float(y.max()), "max_denominator": float(x.max()),
        "delta_numerator": float(np.ptp(y)), "delta_denominator": float(np.ptp(x)),
        "max_marker": _finite_stat(dataset, settings.marker, ni, "max"),
        "longitude": _finite_stat(dataset, settings.longitude, ni),
        "latitude": _finite_stat(dataset, settings.latitude, ni),
        "settings": asdict(settings), "filter_scope": "entire_segment_finite_runs",
        "shift_convention": "numerator[i] versus denominator[i + shift_samples]",
    }
    return FitResult(record, ni, di, y, x)


def montecarlo_result(fit: FitResult, simulations: int = 100, seed: int | None = None,
                      progress: Callable[[int, int], None] = lambda completed, total: None,
                      should_cancel: Callable[[], bool] = lambda: False) -> FitResult:
    """Paired bootstrap OLS slopes; fixed filtering/shift and percentile 95% CI."""
    if isinstance(simulations, bool) or not isinstance(simulations, (int, np.integer)) or not 10 <= simulations <= 1_000_000:
        raise AnalysisError("Monte Carlo requires between 10 and 1,000,000 simulations.")
    if fit.record.get("mode") == "montecarlo":
        raise AnalysisError("Start Monte Carlo from the original OLS fit.")
    if seed is None:
        seed = int(np.random.SeedSequence().generate_state(1, dtype=np.uint32)[0])
    if isinstance(seed, bool) or not isinstance(seed, (int, np.integer)) or not 0 <= seed < 2**64:
        raise AnalysisError("The Monte Carlo seed must be a non-negative integer below 2**64.")
    simulations, seed = int(simulations), int(seed)
    x, y = fit.denominator_values, fit.numerator_values
    size = len(x)
    if size < 3 or len(y) != size or not np.isfinite(x).all() or not np.isfinite(y).all():
        raise AnalysisError("Monte Carlo requires at least three finite paired samples.")
    if np.ptp(x) == 0:
        raise AnalysisError("Monte Carlo cannot fit a constant denominator.")
    rng = np.random.Generator(np.random.PCG64(seed))
    slopes = np.empty(simulations)
    intercepts = np.empty(simulations)
    # Bound temporary arrays independently of N and the selected interval length.
    batch_size = max(1, min(128, 262_144 // size))
    completed = attempted = 0
    attempt_limit = 20 * simulations + 100
    progress(0, simulations)
    while completed < simulations:
        if should_cancel():
            raise InterruptedError("Monte Carlo cancelled; no incomplete confidence interval was saved.")
        count = min(batch_size, simulations - completed, attempt_limit - attempted)
        if count <= 0:
            raise AnalysisError("Too many degenerate resamples to complete Monte Carlo.")
        indices = rng.integers(0, size, size=(count, size))
        bx, by = x[indices], y[indices]
        mx, my = bx.mean(axis=1), by.mean(axis=1)
        dx, dy = bx - mx[:, None], by - my[:, None]
        with np.errstate(over="ignore", invalid="ignore", divide="ignore"):
            ssx = np.einsum("ij,ij->i", dx, dx)
            bslopes = np.einsum("ij,ij->i", dx, dy) / ssx
            bintercepts = my - bslopes * mx
        valid = (ssx > 0) & np.isfinite(bslopes) & np.isfinite(bintercepts)
        accepted = int(valid.sum())
        slopes[completed:completed + accepted] = bslopes[valid]
        intercepts[completed:completed + accepted] = bintercepts[valid]
        completed += accepted
        attempted += count
        progress(completed, simulations)
    if should_cancel():
        raise InterruptedError("Monte Carlo cancelled; no incomplete confidence interval was saved.")
    lower, upper = np.percentile(slopes, [2.5, 97.5], method="linear")
    record = copy.deepcopy(fit.record)
    record.update({
        "result_id": uuid.uuid4().hex, "mode": "montecarlo", "calculated_at": utc_now(),
        "ratio": float(slopes.mean()), "intercept": float(intercepts.mean()),
        "slope_stderr": float(slopes.std(ddof=1)), "slope_ci95_halfwidth": None,
        "ratio_ci95_lower": float(lower), "ratio_ci95_upper": float(upper),
        "ci95_method": "paired_bootstrap_percentile", "p_value": None,
        "simulation_count": simulations, "simulation_seed": seed,
        "ols_reference": copy.deepcopy(fit.record),
        "montecarlo": {"method": "paired_bootstrap_ols_v1", "simulations": simulations,
                       "attempted": attempted, "rejected": attempted - simulations,
                       "seed": seed, "generator": "PCG64", "confidence_level": .95,
                       "quantile_method": "linear", "filter_and_shift_fixed": True,
                       "autocorrelation_corrected": False, "measurement_errors_simulated": False},
        "r_squared_method": "original_ols_on_selected_pairs",
    })
    return FitResult(record, fit.numerator_indices.copy(), fit.denominator_indices.copy(),
                     fit.numerator_values.copy(), fit.denominator_values.copy())


def process_dataset(dataset: Dataset, settings: AnalysisSettings,
                    selection: tuple[int, int] | None = None,
                    progress: Callable[[int, int], None] = lambda completed, total: None,
                    should_cancel: Callable[[], bool] = lambda: False) -> tuple[list[dict], dict]:
    prepared = prepare_signals(dataset, settings)
    lower, upper = selection if selection is not None else (0, len(dataset.frame) - 1)
    if not (0 <= lower <= upper < len(dataset.frame)):
        raise AnalysisError("Invalid processing interval.")
    width = settings.window_width
    margin = settings.max_shift if settings.optimize_shift else 0
    first = max(int(lower), margin)
    last = min(int(upper) - width + 1, len(dataset.frame) - margin - width)
    starts = range(first, last + 1, settings.window_step)
    total = len(starts)
    records = []
    audit = {"run_id": uuid.uuid4().hex, "dataset_id": dataset.id, "dataset": dataset.name,
             "source_sha256": dataset.source_sha256, "started_at": utc_now(),
             "selection": [int(lower), int(upper)], "settings": asdict(settings),
             "windows_total": total, "windows_processed": 0, "accepted": 0,
             "rejected": {}, "status": "completed"}
    rejected = audit["rejected"]
    for completed, start in enumerate(starts, 1):
        if should_cancel():
            audit["status"] = "cancelled"
            break
        stop = start + width - 1
        reason = None
        if settings.marker:
            marker = _finite_stat(dataset, settings.marker, np.arange(start, stop + 1), "max")
            if marker is None or marker < settings.marker_limit:
                reason = "marker_below_threshold"
        if reason is None:
            try:
                fit = fit_interval(dataset, settings, start, stop, prepared, "automatic", should_cancel)
                if fit.record["r"] < 0:
                    reason = "negative_correlation"
                elif fit.record["r_squared"] < settings.r2_limit:
                    reason = "r_squared_below_threshold"
                else:
                    fit.record["run_id"] = audit["run_id"]
                    records.append(fit.record)
            except InterruptedError:
                audit["status"] = "cancelled"
                break
            except AnalysisError:
                reason = "insufficient_or_constant_data"
        if reason:
            rejected[reason] = rejected.get(reason, 0) + 1
        audit["windows_processed"] = completed
        if completed == total or completed % max(1, total // 100) == 0:
            progress(completed, total)
    audit["accepted"] = len(records)
    audit["finished_at"] = utc_now()
    progress(audit["windows_processed"], total)
    return records, audit


def evaluate_water_expression(expression: str, RH, T, P: float) -> np.ndarray:
    """Restricted arithmetic interpreter; no eval or executable Python code."""
    if not (math.isfinite(P) and P > 0):
        raise AnalysisError("Pressure must be positive and expressed in mbar.")
    if len(expression) > 2000:
        raise AnalysisError("The formula is too long.")
    names = {"RH": np.asarray(RH, dtype=float), "T": np.asarray(T, dtype=float), "P": float(P)}
    functions = {"exp": np.exp, "log": np.log, "log10": np.log10,
                 "sqrt": np.sqrt, "abs": np.abs, "clip": np.clip}
    operations = {ast.Add: np.add, ast.Sub: np.subtract, ast.Mult: np.multiply,
                  ast.Div: np.divide, ast.Pow: np.power}

    def walk(node):
        if isinstance(node, ast.Expression):
            return walk(node.body)
        if isinstance(node, ast.Constant) and type(node.value) in (float, int):
            return node.value
        if isinstance(node, ast.Name) and node.id in names:
            return names[node.id]
        if isinstance(node, ast.BinOp) and type(node.op) in operations:
            return operations[type(node.op)](walk(node.left), walk(node.right))
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub)):
            return walk(node.operand) * (-1 if isinstance(node.op, ast.USub) else 1)
        if isinstance(node, ast.Call) and not node.keywords:
            name = node.func.id if isinstance(node.func, ast.Name) else None
            if isinstance(node.func, ast.Attribute) and isinstance(node.func.value, ast.Name):
                if node.func.value.id == "np":
                    name = node.func.attr
            if name in functions:
                return functions[name](*[walk(argument) for argument in node.args])
        raise AnalysisError("Unsupported formula: use RH, T, P, arithmetic operators and exp/log/log10/sqrt/abs/clip.")

    try:
        with np.errstate(all="ignore"):
            values = np.asarray(walk(ast.parse(expression, mode="eval")), dtype=float)
    except (SyntaxError, TypeError, RecursionError) as error:
        raise AnalysisError(f"Invalid formula: {error}") from error
    values = np.broadcast_to(values, names["RH"].shape).copy()
    values[~np.isfinite(values)] = np.nan
    values[(names["RH"] < 0) | (names["RH"] > 100)] = np.nan
    return values


def add_water_channel(dataset: Dataset, rh_column: str, temperature_column: str,
                      pressure: float, expression: str, output_column: str = "H2O_calc") -> None:
    if rh_column not in dataset.frame or temperature_column not in dataset.frame:
        raise AnalysisError("Select the relative humidity and temperature channels.")
    if output_column in dataset.frame.columns:
        raise AnalysisError(f"Channel {output_column!r} already exists; choose a different name.")
    dataset.frame[output_column] = evaluate_water_expression(
        expression, dataset.frame[rh_column], dataset.frame[temperature_column], pressure)
    dataset.derived_channels.append({"column": output_column, "RH_column": rh_column,
                                     "T_column": temperature_column, "pressure_mbar": pressure,
                                     "expression": expression, "units": "ppm", "created_at": utc_now()})


def _json_default(value):
    if isinstance(value, (datetime, pd.Timestamp, Path)):
        return str(value)
    if isinstance(value, np.integer):
        return int(value)
    if isinstance(value, np.floating):
        return float(value)
    raise TypeError(f"Unsupported serialization type: {type(value).__name__}")


def json_text(value) -> str:
    return json.dumps(value, ensure_ascii=False, indent=2, default=_json_default, allow_nan=False)


def atomic_text(path: str | Path, text: str) -> None:
    target = Path(path)
    handle, temporary = tempfile.mkstemp(prefix=target.name + ".", dir=target.parent)
    try:
        with os.fdopen(handle, "w", encoding="utf-8", newline="") as stream:
            stream.write(text)
        os.replace(temporary, target)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)


def dataset_payload(dataset: Dataset) -> dict:
    # Encode missing values as null and dates as ISO strings.
    frame = dataset.frame.copy()
    is_datetime = pd.api.types.is_datetime64_any_dtype(frame.iloc[:, 0].dtype)
    if is_datetime:
        frame[frame.columns[0]] = frame.iloc[:, 0].map(lambda value: value.isoformat())
    # Standard JSON serialization preserves round-trip float representations.
    # DataFrame.to_json(double_precision=15) would lose the last bits.
    data = {"columns": list(frame.columns), "index": list(range(len(frame))),
            "data": [[None if pd.isna(value) else value for value in row]
                     for row in frame.itertuples(index=False, name=None)]}
    return {"id": dataset.id, "name": dataset.name, "source_path": dataset.source_path,
            "source_sha256": dataset.source_sha256, "import_options": dataset.import_options,
            "derived_channels": dataset.derived_channels, "time_is_datetime": is_datetime,
            "frame": data}


def save_project(path: str | Path, datasets: list[Dataset], settings: AnalysisSettings,
                 manual_results: list, automatic_results: list, runs: list, ui_state: dict) -> None:
    manifest = {"schema": PROJECT_SCHEMA, "schema_version": PROJECT_VERSION,
                "saved_at": utc_now(), "environment": environment_versions(),
                "settings": asdict(settings), "manual_results": manual_results,
                "automatic_results": automatic_results, "runs": runs, "ui_state": ui_state,
                "datasets": [f"datasets/{index:04d}.json" for index in range(len(datasets))],
                "calculation_rules": {"shift": "numerator[i] vs denominator[i+s]",
                                       "filter_scope": "entire segment; finite runs separately",
                                       "regression": "OLS with intercept",
                                       "ci95": "OLS: Student t, n-2 degrees of freedom; Monte Carlo: paired-bootstrap percentiles",
                                       "montecarlo": "Resample aligned finite pairs with replacement; filters and shift fixed"}}
    target = Path(path)
    handle, temporary = tempfile.mkstemp(prefix=target.name + ".", dir=target.parent)
    os.close(handle)
    try:
        with zipfile.ZipFile(temporary, "w", compression=zipfile.ZIP_DEFLATED) as archive:
            archive.writestr("manifest.json", json_text(manifest))
            for index, dataset in enumerate(datasets):
                archive.writestr(manifest["datasets"][index], json_text(dataset_payload(dataset)))
        os.replace(temporary, target)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)


def load_project(path: str | Path) -> tuple[list[Dataset], dict]:
    with zipfile.ZipFile(path) as archive:
        manifest = json.loads(archive.read("manifest.json"))
        if manifest.get("schema") != PROJECT_SCHEMA or manifest.get("schema_version") != PROJECT_VERSION:
            raise AnalysisError("Unsupported project format or version.")
        datasets = []
        for entry in manifest["datasets"]:
            payload = json.loads(archive.read(entry))
            frame = pd.DataFrame(payload["frame"]["data"], columns=payload["frame"]["columns"])
            if payload["time_is_datetime"]:
                frame[frame.columns[0]] = pd.to_datetime(frame.iloc[:, 0], format="ISO8601")
            for column in frame.columns[1:]:
                frame[column] = pd.to_numeric(frame[column], errors="coerce").astype(float)
            datasets.append(Dataset(payload["name"], frame, payload["source_path"],
                                    payload["source_sha256"], payload["id"],
                                    payload["import_options"], payload["derived_channels"]))
    if not datasets:
        raise AnalysisError("The project contains no datasets.")
    AnalysisSettings.from_dict(manifest["settings"]).validate(datasets[manifest["ui_state"].get("active_dataset", 0)])
    return datasets, manifest


def result_frame(records: list[dict], include_metadata: bool = False) -> pd.DataFrame:
    preferred = ["dataset", "time", "numerator", "denominator", "ratio", "intercept",
                 "r_squared", "n_samples", "shift_samples", "shift_seconds", "selection_start",
                 "selection_end", "ratio_ci95_lower", "ratio_ci95_upper", "ci95_method",
                 "simulation_count", "slope_ci95_halfwidth", "max_numerator", "max_denominator",
                 "max_marker", "longitude", "latitude", "mode"]
    if not records:
        return pd.DataFrame(columns=preferred)
    if include_metadata:
        flattened = []
        for record in records:
            row = dict(record)
            for key, value in row.items():
                if isinstance(value, (dict, list)):
                    row[key] = json.dumps(value, ensure_ascii=False, sort_keys=True)
            flattened.append(row)
        return pd.DataFrame(flattened)
    return pd.DataFrame(records).reindex(columns=preferred)


def export_results(path: str | Path, records: list[dict], datasets: list[Dataset], runs: list) -> tuple[Path, Path]:
    if not records:
        raise AnalysisError("No results to export.")
    target = Path(path)
    metadata = target.with_suffix(".metadata.json")
    csv = result_frame(records, include_metadata=True).to_csv(index=False, float_format="%.17g")
    audit = {"exported_at": utc_now(), "environment": environment_versions(), "records": records,
             "runs": runs, "datasets": [{"id": data.id, "name": data.name,
                    "source_path": data.source_path, "source_sha256": data.source_sha256,
                    "import_options": data.import_options, "derived_channels": data.derived_channels}
                    for data in datasets], "project_required_for_embedded_raw_data": True}
    atomic_text(metadata, json_text(audit))
    atomic_text(target, csv)
    return target, metadata


def demo_datasets() -> list[Dataset]:
    """Deterministic synthetic data: three segments, CO2/SO2 = 4 and shift +3."""
    generator = np.random.default_rng(2015)
    segments = []
    for number in range(3):
        size = 520
        index = np.arange(size)
        pulse = (35 * np.exp(-((index - 145) / 35) ** 2) +
                 65 * np.exp(-((index - 320) / 45) ** 2))
        so2 = 0.7 + pulse + generator.normal(0, 0.25, size)
        co2 = np.full(size, np.nan)
        co2[:-3] = 410 + 4 * so2[3:] + generator.normal(0, 0.5, size - 3)
        times = pd.date_range("2026-01-01 09:00:00", periods=size, freq="s") + pd.Timedelta(minutes=15 * number)
        frame = pd.DataFrame({"Time": times, "CO2_ppm": co2, "SO2_ppm": so2,
                              "RH_percent": 55 + 2 * np.sin(index / 40),
                              "T_celsius": 22 + 0.5 * np.cos(index / 70),
                              "Longitude": 15.21 + index / 100000,
                              "Latitude": 38.79 + np.sin(index / 100) / 1000})
        segments.append(Dataset(f"Synthetic example · segment {number + 1}", frame,
                                "synthetic", "", id=f"demo-{number + 1}",
                                import_options={"synthetic": True, "seed": 2015,
                                                "known_ratio": 4, "known_shift": 3}))
    return segments



import hashlib
import math
from dataclasses import asdict, dataclass
from pathlib import Path

import numpy as np
import pandas as pd
from scipy.interpolate import CloughTocher2DInterpolator
from scipy.spatial import ConvexHull, QhullError, cKDTree



@dataclass
class SpatialSettings:
    x_channel: str = ""
    y_channel: str = ""
    z_channel: str = ""
    method: str = "idw"
    cells_x: int = 100
    cells_y: int = 100
    coordinate_mode: str = "cartesian"
    cartesian_reference: str = ""
    idw_power: float = 2.0
    idw_neighbors: int = 12
    idw_radius: float = 0.0
    duplicate_policy: str = "mean"
    only_selection: bool = False

    def validate(self, dataset=None):
        if self.x_channel == self.y_channel or not all((self.x_channel, self.y_channel, self.z_channel)):
            raise AnalysisError("Select X, Y and Z channels; X and Y must be different.")
        if dataset is not None and any(name not in dataset.frame.columns[1:]
                                       for name in (self.x_channel, self.y_channel, self.z_channel)):
            raise AnalysisError("The selected spatial channels are not present in this dataset.")
        for size in (self.cells_x, self.cells_y):
            if isinstance(size, bool) or not isinstance(size, (int, np.integer)) or not 1 <= size <= 2000:
                raise AnalysisError("Cells X and Cells Y must be integers between 1 and 2,000.")
        if self.cells_x * self.cells_y > 1_000_000:
            raise AnalysisError("The grid cannot exceed 1,000,000 cells. Reduce Cells X or Cells Y.")
        if self.method not in {"idw", "cubic"} or self.coordinate_mode not in {"cartesian", "wgs84"}:
            raise AnalysisError("Unsupported interpolation method or coordinate mode.")
        if self.duplicate_policy not in {"mean", "median"}:
            raise AnalysisError("Choose mean or median for duplicate coordinates.")
        if not math.isfinite(self.idw_power) or not 0 < self.idw_power <= 20:
            raise AnalysisError("IDW power must be greater than 0 and at most 20.")
        if isinstance(self.idw_neighbors, bool) or not isinstance(self.idw_neighbors, (int, np.integer)) or not 1 <= self.idw_neighbors <= 10_000:
            raise AnalysisError("IDW neighbors must be between 1 and 10,000.")
        if not math.isfinite(self.idw_radius) or self.idw_radius < 0:
            raise AnalysisError("IDW radius must be finite and non-negative; zero means unlimited.")


def prepare_spatial_points(dataset, settings, selection=None):
    settings.validate(dataset)
    lower, upper = selection if settings.only_selection and selection is not None else (0, len(dataset.frame) - 1)
    if not 0 <= lower <= upper < len(dataset.frame):
        raise AnalysisError("The spatial source interval is outside the dataset.")
    raw = dataset.frame.iloc[lower:upper + 1][
        [settings.x_channel, settings.y_channel, settings.z_channel]].to_numpy(dtype=float)
    valid = np.isfinite(raw).all(axis=1)
    values = raw[valid]
    if not len(values):
        raise AnalysisError("No finite X, Y, Z samples are available in the source interval.")
    digest = hashlib.sha256()
    digest.update(np.asarray(np.flatnonzero(valid) + lower, dtype="<i8").tobytes())
    digest.update(np.asarray(values, dtype="<f8").tobytes())
    frame = pd.DataFrame(values, columns=["x", "y", "z"])
    grouped = frame.groupby(["x", "y"], sort=True)["z"].agg(settings.duplicate_policy).reset_index()
    points = grouped[["x", "y"]].to_numpy(float)
    z = grouped["z"].to_numpy(float)
    info = {"source_row_range": [int(lower), int(upper)], "source_rows": len(raw),
            "finite_rows": int(valid.sum()), "invalid_rows": int((~valid).sum()),
            "unique_points": len(points), "duplicate_rows": len(values) - len(points),
            "source_signature": digest.hexdigest()}
    return points, z, info


def validate_polygon(vertices):
    polygon = np.asarray(vertices, dtype=float)
    if polygon.ndim != 2 or polygon.shape[1:] != (2,) or not 3 <= len(polygon) <= 1001 or not np.isfinite(polygon).all():
        raise AnalysisError("Draw a polygon with at least three finite vertices (maximum 1,000).")
    if np.array_equal(polygon[0], polygon[-1]):
        polygon = polygon[:-1]
    if not 3 <= len(polygon) <= 1000:
        raise AnalysisError("The polygon needs at least three different vertices.")
    span = np.ptp(polygon, axis=0)
    scale = float(span.max())
    if scale == 0 or np.any(span == 0):
        raise AnalysisError("The polygon must enclose a non-zero area.")
    p = (polygon - polygon.min(axis=0)) / scale
    if len(np.unique(p, axis=0)) != len(p):
        raise AnalysisError("The polygon contains repeated vertices.")
    def cross(u, v):
        return u[..., 0] * v[..., 1] - u[..., 1] * v[..., 0]
    def on_segment(a, b, c):
        return np.all(c >= np.minimum(a, b) - 1e-12, axis=-1) & np.all(c <= np.maximum(a, b) + 1e-12, axis=-1)
    count = len(p)
    for i in range(count):
        a, b = p[i], p[(i + 1) % count]
        js = np.arange(i + 2, count - (1 if i == 0 else 0))
        if not len(js):
            continue
        c, d = p[js], p[(js + 1) % count]
        v = (cross(b - a, c - a), cross(b - a, d - a), cross(d - c, a - c), cross(d - c, b - c))
        crossing = (v[0] * v[1] < 0) & (v[2] * v[3] < 0)
        touching = np.zeros(len(js), dtype=bool)
        for value, args in zip(v, ((a, b, c), (a, b, d), (c, d, a), (c, d, b))):
            touching |= (np.abs(value) <= 1e-12) & on_segment(*args)
        if np.any(crossing | touching):
            raise AnalysisError("The polygon crosses or touches itself. Redraw a simple boundary.")
    area = np.sum(p[:, 0] * np.roll(p[:, 1], -1) - p[:, 1] * np.roll(p[:, 0], -1))
    if abs(area) <= 1e-12:
        raise AnalysisError("The polygon must enclose a non-zero area.")
    return polygon.copy()


def polygon_contains(points, vertices):
    from matplotlib.path import Path as MplPath
    polygon = np.asarray(vertices, dtype=float)
    origin = polygon.min(axis=0)
    scale = max(float(np.ptp(polygon, axis=0).max()), np.finfo(float).tiny)
    p = (polygon - origin) / scale
    area = np.sum(p[:, 0] * np.roll(p[:, 1], -1) - p[:, 1] * np.roll(p[:, 0], -1))
    if area < 0:
        p = p[::-1]
    return MplPath(np.vstack([p, p[0]]), closed=True).contains_points(
        (np.asarray(points) - origin) / scale, radius=2e-12)


def spatial_hull(points):
    try:
        points = np.asarray(points, dtype=float)
        return validate_polygon(points[ConvexHull(points).vertices]).tolist()
    except (QhullError, ValueError):
        raise AnalysisError("A convex hull requires at least three non-collinear locations. Draw a polygon for IDW.") from None


def spatial_projection(points, polygon, settings):
    if settings.coordinate_mode == "cartesian":
        return lambda values: np.asarray(values, dtype=float), {
            "input_crs": settings.cartesian_reference or "Cartesian (user supplied)",
            "working_crs": settings.cartesian_reference or "same as input",
            "distance_units": "input XY units", "export_coordinate_units": "input XY units"}
    try:
        from pyproj import CRS, Transformer
    except ImportError:
        raise AnalysisError("Geographic interpolation requires pyproj. Install the updated requirements.txt.") from None
    all_xy = np.vstack([points, polygon])
    lon, lat = all_xy[:, 0], all_xy[:, 1]
    if np.any(np.abs(lon) > 180) or np.any(np.abs(lat) > 90):
        raise AnalysisError("WGS84 requires X longitude in [-180, 180] and Y latitude in [-90, 90].")
    if np.ptp(lon) > 180:
        raise AnalysisError("Areas crossing the date line must be supplied in projected Cartesian coordinates.")
    lon0, lat0 = float(lon.mean()), float(lat.mean())
    if -80 <= lat0 <= 84:
        zone = min(60, max(1, int((lon0 + 180) // 6) + 1))
        target = CRS.from_epsg((32600 if lat0 >= 0 else 32700) + zone)
    else:
        target = CRS.from_proj4(f"+proj=aeqd +lat_0={lat0} +lon_0={lon0} +datum=WGS84 +units=m")
    transformer = Transformer.from_crs("EPSG:4326", target, always_xy=True)
    def transform(values):
        values = np.asarray(values, dtype=float)
        x, y = transformer.transform(values[:, 0], values[:, 1], errcheck=True)
        result = np.column_stack([x, y])
        if not np.isfinite(result).all():
            raise AnalysisError("The coordinate projection produced invalid locations.")
        return result
    return transform, {"input_crs": "EPSG:4326", "working_crs": target.to_string(),
                       "distance_units": "m", "export_coordinate_units": "degrees (longitude, latitude)"}


@dataclass
class SpatialResult:
    x: np.ndarray
    y: np.ndarray
    values: np.ndarray
    inside: np.ndarray
    metadata: dict

    def payload(self):
        values = self.values.astype(object)
        values[~np.isfinite(self.values)] = None
        return {"x": self.x.tolist(), "y": self.y.tolist(), "values": values.tolist(),
                "inside": self.inside.tolist(), "metadata": self.metadata}

    @classmethod
    def from_payload(cls, payload):
        x, y = np.asarray(payload["x"], float), np.asarray(payload["y"], float)
        values = np.asarray(payload["values"], float)
        inside = np.asarray(payload["inside"], bool)
        if (x.ndim != 1 or y.ndim != 1 or not 1 <= len(x) * len(y) <= 1_000_000 or
            values.shape != (len(y), len(x)) or inside.shape != values.shape or
            not np.isfinite(x).all() or not np.isfinite(y).all() or
            not np.all(np.diff(x) > 0) or not np.all(np.diff(y) < 0)):
            raise AnalysisError("Invalid spatial grid in the project.")
        values[~inside] = np.nan
        return cls(x, y, values, inside, payload["metadata"])


def interpolate_spatial(dataset, settings, vertices, selection=None,
                        progress=lambda percent, text: None, should_cancel=lambda: False):
    def check_cancel():
        if should_cancel():
            raise InterruptedError("Spatial interpolation cancelled; no incomplete grid was saved.")
    check_cancel()
    settings.validate(dataset)
    polygon = validate_polygon(vertices)
    points, z, info = prepare_spatial_points(dataset, settings, selection)
    support = polygon_contains(points, polygon)
    points, z = points[support], z[support]
    if not len(points):
        raise AnalysisError("The polygon contains no valid data points.")
    transform, projection = spatial_projection(points, polygon, settings)
    xy = transform(points)
    center = xy.mean(axis=0)
    xy = xy - center  # Translation improves triangulation precision without changing distances.
    check_cancel()
    progress(5, "Preparing spatial interpolation…")
    if settings.method == "cubic":
        if len(xy) < 3 or np.linalg.matrix_rank(xy) < 2:
            raise AnalysisError("Cubic interpolation requires at least three non-collinear locations inside the polygon.")
        try:
            model = CloughTocher2DInterpolator(xy, z, fill_value=np.nan)
        except (QhullError, ValueError) as error:
            raise AnalysisError(f"Could not triangulate these locations: {error}") from error
        neighbors = 1
    else:
        model = cKDTree(xy)
        neighbors = min(settings.idw_neighbors, len(xy))
    check_cancel()
    xmin, ymin = polygon.min(axis=0)
    xmax, ymax = polygon.max(axis=0)
    dx, dy = (xmax - xmin) / settings.cells_x, (ymax - ymin) / settings.cells_y
    x = xmin + (np.arange(settings.cells_x) + .5) * dx
    y = ymax - (np.arange(settings.cells_y) + .5) * dy
    if not np.all(np.diff(x) > 0) or not np.all(np.diff(y) < 0):
        raise AnalysisError("Cell spacing is smaller than coordinate precision. Reduce the grid size.")
    gx, gy = np.meshgrid(x, y)
    locations = np.column_stack([gx.ravel(), gy.ravel()])
    mask = polygon_contains(locations, polygon)
    targets = np.flatnonzero(mask)
    if not len(targets):
        raise AnalysisError("No cell centers fall inside the polygon. Increase the grid resolution.")
    output = np.full(len(locations), np.nan)
    chunk = max(1, min(4096, 262144 // neighbors))
    for start in range(0, len(targets), chunk):
        check_cancel()
        rows = targets[start:start + chunk]
        query = transform(locations[rows]) - center
        if settings.method == "cubic":
            estimates = np.asarray(model(query), float)
        else:
            radius = np.nextafter(settings.idw_radius, np.inf) if settings.idw_radius else np.inf
            distance, indices = model.query(query, k=neighbors, distance_upper_bound=radius)
            distance, indices = distance.reshape(len(rows), neighbors), indices.reshape(len(rows), neighbors)
            valid = np.isfinite(distance) & (indices < len(z))
            nearby = z[np.minimum(indices, len(z) - 1)]
            exact = valid & (distance == 0)
            minimum = np.min(np.where(valid & (distance > 0), distance, np.inf), axis=1)
            minimum[~np.isfinite(minimum)] = 1
            with np.errstate(divide="ignore", invalid="ignore", over="ignore"):
                weights = np.where(valid & (distance > 0), (minimum[:, None] / distance) ** settings.idw_power, 0)
                estimates = np.sum(weights * nearby, axis=1) / weights.sum(axis=1)
            has_exact = exact.any(axis=1)
            estimates[has_exact] = nearby[has_exact, exact[has_exact].argmax(axis=1)]
        estimates[~np.isfinite(estimates)] = np.nan
        output[rows] = estimates
        progress(10 + int(90 * min(start + chunk, len(targets)) / len(targets)), "Interpolating grid cells…")
    check_cancel()
    values = output.reshape(len(y), len(x))
    metadata = {"schema": "ratiocalc.spatial.grid", "schema_version": 1, "calculated_at": utc_now(),
                "dataset_id": dataset.id, "dataset": dataset.name, "source_path": dataset.source_path,
                "source_sha256": dataset.source_sha256, "settings": asdict(settings), "polygon": polygon.tolist(),
                "bounds": [float(xmin), float(xmax), float(ymin), float(ymax)],
                "cell_size": [float(dx), float(dy)], "grid_shape": [len(y), len(x)],
                "grid_cells": int(values.size), "inside_cells": int(mask.sum()),
                "estimated_cells": int(np.isfinite(values).sum()), "support_points": len(points),
                "source": info, "projection": projection, "environment": environment_versions(),
                "rows": "Y cell centers, descending", "columns": "X cell centers, ascending",
                "mask_rule": "cell center inside or on polygon boundary; use only input points inside polygon",
                "cubic_extrapolation": False, "missing_value": "NaN"}
    return SpatialResult(x, y, values, mask.reshape(values.shape), metadata)


def export_spatial(path, result):
    target = Path(path)
    frame = pd.DataFrame(result.values, index=result.y, columns=[f"{value:.17g}" for value in result.x])
    csv = frame.to_csv(index_label="Y / X", float_format="%.17g", na_rep="NaN")
    metadata_path = target.with_suffix(".metadata.json")
    metadata = dict(result.metadata, exported_at=utc_now(), csv_sha256=hashlib.sha256(csv.encode()).hexdigest())
    atomic_text(metadata_path, json_text(metadata))
    atomic_text(target, csv)
    return target, metadata_path



