def configure_application(app):
    """Apply one English, light appearance to windows, popups and controls."""
    QtCore.QLocale.setDefault(QtCore.QLocale(QtCore.QLocale.Language.English,
                                            QtCore.QLocale.Country.UnitedStates))
    app.setAttribute(Qt.ApplicationAttribute.AA_DontUseNativeDialogs, True)
    app.setStyle("Fusion")
    hints = app.styleHints()
    if hasattr(hints, "setColorScheme"):
        hints.setColorScheme(Qt.ColorScheme.Light)
    palette = QtGui.QPalette()
    role_colors = {
        "Window": "#f3f5f8", "WindowText": "#26354a", "Base": "#ffffff",
        "AlternateBase": "#f5f8fa", "Text": "#26354a", "Button": "#f8fafc",
        "ButtonText": "#26354a", "BrightText": "#ffffff", "Highlight": "#d0e8df",
        "HighlightedText": "#153a32", "ToolTipBase": "#ffffff", "ToolTipText": "#26354a",
        "PlaceholderText": "#687a8f", "Light": "#ffffff", "Midlight": "#edf2f6",
        "Mid": "#cbd5df", "Dark": "#8194a7", "Shadow": "#52657a",
        "Link": "#176f9a", "LinkVisited": "#6354a2",
    }
    for group in (QtGui.QPalette.ColorGroup.Active, QtGui.QPalette.ColorGroup.Inactive,
                  QtGui.QPalette.ColorGroup.Disabled):
        for role, color in role_colors.items():
            palette.setColor(group, getattr(QtGui.QPalette.ColorRole, role), QtGui.QColor(color))
    for role in (QtGui.QPalette.ColorRole.Text, QtGui.QPalette.ColorRole.WindowText,
                 QtGui.QPalette.ColorRole.ButtonText):
        palette.setColor(QtGui.QPalette.ColorGroup.Disabled, role, QtGui.QColor("#7b8998"))
    app.setPalette(palette)
    app.setStyleSheet(STYLE)


class CheckBox(QtWidgets.QCheckBox):
    """A visible check mark, independent of the desktop's checkbox artwork."""
    def __init__(self, text="", parent=None):
        super().__init__(text, parent)
        self.setObjectName("visibleCheckBox")

    def paintEvent(self, event):
        super().paintEvent(event)
        if self.checkState() == Qt.CheckState.Unchecked:
            return
        option = QtWidgets.QStyleOptionButton()
        self.initStyleOption(option)
        rect = self.style().subElementRect(QtWidgets.QStyle.SubElement.SE_CheckBoxIndicator, option, self)
        painter = QtGui.QPainter(self)
        painter.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing)
        painter.setPen(QtGui.QPen(QtGui.QColor("#ffffff"), 2.2,
                                 Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
        if self.checkState() == Qt.CheckState.PartiallyChecked:
            painter.drawLine(QtCore.QPointF(rect.left() + 4, rect.center().y()),
                             QtCore.QPointF(rect.right() - 4, rect.center().y()))
        else:
            painter.drawPolyline(QtGui.QPolygonF([
                QtCore.QPointF(rect.left() + rect.width() * .23, rect.top() + rect.height() * .52),
                QtCore.QPointF(rect.left() + rect.width() * .43, rect.top() + rect.height() * .72),
                QtCore.QPointF(rect.left() + rect.width() * .77, rect.top() + rect.height() * .29),
            ]))
        painter.end()


def spin(minimum, maximum, value, decimals=None, suffix=""):
    box = QtWidgets.QDoubleSpinBox() if decimals is not None else QtWidgets.QSpinBox()
    if decimals is not None:
        box.setDecimals(decimals)
    box.setRange(minimum, maximum)
    box.setValue(value)
    box.setSuffix(suffix)
    box.setKeyboardTracking(False)
    return box


def button(text, callback, primary=False):
    widget = QtWidgets.QPushButton(text)
    if primary:
        widget.setObjectName("primary")
    widget.clicked.connect(callback)
    return widget


class DataFrameModel(QtCore.QAbstractTableModel):
    def __init__(self, parent=None):
        super().__init__(parent)
        import pandas as pd
        self.frame = pd.DataFrame()

    def set_frame(self, frame):
        self.beginResetModel()
        self.frame = frame.copy()
        self.endResetModel()

    def rowCount(self, parent=QtCore.QModelIndex()):
        return 0 if parent.isValid() else len(self.frame)

    def columnCount(self, parent=QtCore.QModelIndex()):
        return 0 if parent.isValid() else len(self.frame.columns)

    def data(self, index, role=Qt.ItemDataRole.DisplayRole):
        if not index.isValid():
            return None
        value = self.frame.iat[index.row(), index.column()]
        if role in (Qt.ItemDataRole.DisplayRole, Qt.ItemDataRole.ToolTipRole):
            import pandas as pd
            if pd.isna(value):
                return ""
            if isinstance(value, float):
                return f"{value:.7g}" if role == Qt.ItemDataRole.DisplayRole else repr(value)
            return str(value)
        if role == Qt.ItemDataRole.TextAlignmentRole:
            import numpy as np
            if isinstance(value, (float, int, np.number)):
                return int(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
        return None

    def headerData(self, section, orientation, role=Qt.ItemDataRole.DisplayRole):
        if role == Qt.ItemDataRole.DisplayRole:
            return str(self.frame.columns[section]) if orientation == Qt.Orientation.Horizontal else str(section)
        return None


class DataFrameView(QtWidgets.QTableView):
    def keyPressEvent(self, event):
        if event.matches(QtGui.QKeySequence.StandardKey.Copy):
            rows = sorted({index.row() for index in self.selectionModel().selectedRows()})
            if rows:
                text = self.model().frame.iloc[rows].to_csv(sep="\t", index=False, float_format="%.17g")
                QtGui.QGuiApplication.clipboard().setText(text)
            event.accept()
            return
        super().keyPressEvent(event)


class FilterEditor(QtWidgets.QGroupBox):
    changed = QtCore.Signal()

    def __init__(self, title):
        super().__init__(title)
        form = QtWidgets.QFormLayout(self)
        self.method = QtWidgets.QComboBox()
        for label, code in FILTER_LABELS.items():
            self.method.addItem(label, code)
        self.alpha = spin(0.001, 1, 0.3, 3)
        self.window = spin(3, 999, 5)
        self.window.setSingleStep(2)
        self.polyorder = spin(0, 20, 2)
        form.addRow(self.method)
        form.addRow("Alpha", self.alpha)
        form.addRow("Window", self.window)
        form.addRow("Order", self.polyorder)
        self.form = form
        self.method.currentIndexChanged.connect(self._method_changed)
        for editor in (self.alpha, self.window, self.polyorder):
            editor.valueChanged.connect(self.changed.emit)
        self._method_changed()

    def _method_changed(self):
        method = self.method.currentData()
        for editor, visible in ((self.alpha, method == "exponential"),
                                (self.window, method in {"savgol", "moving_average"}),
                                (self.polyorder, method == "savgol")):
            editor.setVisible(visible)
            self.form.labelForField(editor).setVisible(visible)
        self.changed.emit()

    def value(self):
        return FilterSpec(self.method.currentData(), self.alpha.value(),
                          self.window.value(), self.polyorder.value())

    def set_value(self, spec):
        self.method.setCurrentIndex(self.method.findData(spec.method))
        self.alpha.setValue(spec.alpha)
        self.window.setValue(spec.window)
        self.polyorder.setValue(spec.polyorder)


class PlotPanel(QtWidgets.QWidget):
    interval_selected = QtCore.Signal(int, int)
    key_action = QtCore.Signal(str)

    def __init__(self):
        super().__init__()
        self.figure = Figure(figsize=(10, 7), dpi=100, facecolor="white", layout="constrained")
        grid = self.figure.add_gridspec(2, 2, height_ratios=[1.15, 1])
        self.overview = self.figure.add_subplot(grid[0, :])
        self.overview_den = self.overview.twinx()
        self.scatter = self.figure.add_subplot(grid[1, 0])
        self.aligned = self.figure.add_subplot(grid[1, 1])
        self.aligned_den = self.aligned.twinx()
        self.canvas = FigureCanvasQTAgg(self.figure)
        self.canvas.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        self.toolbar = NavigationToolbar2QT(self.canvas, self)
        self.selector = None
        self.size = 0
        self.options = dict(COLORS)
        self.settings = None
        self.dataset_id = None
        self.num_line, self.den_line = None, None
        self.start_line, self.end_line = None, None
        self.canvas.mpl_connect("key_press_event", lambda event: self.key_action.emit(event.key or ""))
        layout = QtWidgets.QVBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.addWidget(self.toolbar)
        layout.addWidget(self.canvas, 1)
        self.overview.set_title("Open a data file or load the synthetic example", fontsize=12)
        for axis in (self.overview, self.scatter, self.aligned):
            axis.tick_params(labelsize=9)

    def set_signals(self, dataset, settings, prepared, options):
        import numpy as np
        if self.selector is not None:
            self.selector.disconnect_events()
            self.selector = None
        self.settings, self.options = settings, dict(options)
        self.dataset_id, self.size = dataset.id, len(dataset.frame)
        for axis in (self.overview, self.overview_den):
            axis.clear()
        self.overview_den.yaxis.set_label_position("right")
        self.overview_den.yaxis.tick_right()
        # Downsample only the display; the engine still uses every sample.
        stride = max(1, math.ceil(self.size / 50000))
        indices = np.arange(self.size)[::stride]
        self.overview.plot(indices, dataset.frame[settings.numerator].to_numpy()[::stride],
                           color=options["numerator_color"], linewidth=options["line_width"], alpha=.85)
        self.overview_den.plot(indices, dataset.frame[settings.denominator].to_numpy()[::stride],
                               color=options["denominator_color"], linewidth=options["line_width"], alpha=.85)
        self.overview.set_title("Original signals · drag to select an interval", fontsize=11, loc="left")
        self.overview.set_xlabel("Sample", fontsize=9)
        self.overview.set_ylabel(settings.numerator, color=options["numerator_color"], fontsize=9)
        self.overview_den.set_ylabel(settings.denominator, color=options["denominator_color"], fontsize=9)
        self.overview.set_xlim(0, max(1, self.size - 1))
        self.overview.grid(alpha=.15)
        # The upper axis receives events even when a twin axis is present.
        self.overview.set_zorder(self.overview_den.get_zorder() + 1)
        self.overview.patch.set_visible(False)
        self.selector = SpanSelector(self.overview, self._selected, "horizontal", useblit=True,
                                     props=dict(facecolor="#259781", alpha=.16), interactive=True,
                                     drag_from_anywhere=True, button=1, minspan=2)
        self.overview.tick_params(labelsize=9)
        self.overview_den.tick_params(labelsize=9)
        self.canvas.draw_idle()

    def _selected(self, left, right):
        if self.toolbar.mode or not self.size:
            return
        start = max(0, min(self.size - 1, int(math.ceil(left))))
        end = max(start, min(self.size - 1, int(math.floor(right))))
        self.interval_selected.emit(start, end)
        self.canvas.setFocus()

    def set_interval(self, start, end):
        if self.selector is not None:
            self.selector.extents = (start, end)
            self.selector.set_visible(True)

    def show_fit(self, fit, settings):
        import numpy as np
        for axis in (self.scatter, self.aligned, self.aligned_den):
            axis.clear()
        self.aligned_den.yaxis.set_label_position("right")
        self.aligned_den.yaxis.tick_right()
        self.scatter.set_title("Regression · processed signals", fontsize=11, loc="left")
        self.scatter.set_xlabel(settings.denominator, fontsize=9)
        self.scatter.set_ylabel(settings.numerator, fontsize=9)
        self.aligned.set_title("Filtered and aligned interval", fontsize=11, loc="left")
        self.aligned.set_xlabel("Numerator sample", fontsize=9)
        self.aligned.set_ylabel(settings.numerator, color=self.options["numerator_color"], fontsize=9)
        self.aligned_den.set_ylabel(settings.denominator, color=self.options["denominator_color"], fontsize=9)
        if fit is not None:
            record = fit.record
            if record.get("mode") == "montecarlo":
                self.scatter.set_title("Monte Carlo mean regression", fontsize=11, loc="left")
            x, y = fit.denominator_values, fit.numerator_values
            self.scatter.scatter(x, y, s=self.options["scatter_size"],
                                 color=self.options["scatter_color"], alpha=.6, linewidths=0)
            bounds = np.array([x.min(), x.max()])
            self.scatter.plot(bounds, record["ratio"] * bounds + record["intercept"],
                              color="#c77344", linewidth=1.6)
            if self.options["show_equation"]:
                r_label = "OLS R²" if record.get("mode") == "montecarlo" else "R²"
                equation = (f"y = {record['ratio']:.4g} x + {record['intercept']:.4g}\n"
                            f"{r_label} = {record['r_squared']:.4f} · n = {record['n_samples']}")
                self.scatter.text(.04, .96, equation, transform=self.scatter.transAxes,
                                  va="top", fontsize=8, color="#425367")
            self.aligned.plot(fit.numerator_indices, y, color=self.options["numerator_color"],
                              linewidth=self.options["line_width"])
            self.aligned_den.plot(fit.numerator_indices, x, color=self.options["denominator_color"],
                                  linewidth=self.options["line_width"])
        else:
            self.scatter.text(.5, .5, "Select a valid interval", ha="center", va="center",
                              transform=self.scatter.transAxes, fontsize=10, color="#789")
        for axis in (self.scatter, self.aligned):
            axis.grid(alpha=.15)
            axis.tick_params(labelsize=9)
        self.aligned_den.tick_params(labelsize=9)
        self.canvas.draw_idle()


class ProcessingThread(QtCore.QThread):
    progress_changed = QtCore.Signal(int, str)
    results_ready = QtCore.Signal(object, object)
    failed = QtCore.Signal(str)

    def __init__(self, datasets, settings, selections, parent=None):
        super().__init__(parent)
        # Take a snapshot; the interface cannot change data during processing.
        self.datasets = copy.deepcopy(datasets)
        self.settings = copy.deepcopy(settings)
        self.selections = dict(selections)
        self.cancel_event = threading.Event()

    def request_stop(self):
        # Event also handles cancellation requested before QThread starts.
        self.cancel_event.set()
        self.requestInterruption()

    def run(self):
        records, runs = [], []
        try:
            for number, dataset in enumerate(self.datasets):
                if self.cancel_event.is_set():
                    break

                def report(completed, total, dataset=dataset, number=number):
                    fraction = completed / total if total else 1.0
                    percent = int(100 * (number + fraction) / len(self.datasets))
                    self.progress_changed.emit(percent, f"{dataset.name} · {completed}/{total} windows")

                rows, audit = process_dataset(dataset, self.settings, self.selections.get(dataset.id),
                                              report, self.cancel_event.is_set)
                records.extend(rows)
                runs.append(audit)
                if audit["status"] == "cancelled":
                    break
            self.results_ready.emit(records, runs)
        except Exception:
            self.failed.emit(traceback.format_exc())


class MonteCarloThread(QtCore.QThread):
    progress_changed = QtCore.Signal(int, str)
    results_ready = QtCore.Signal(object, object)
    failed = QtCore.Signal(str)

    def __init__(self, fit, simulations, parent=None):
        super().__init__(parent)
        self.fit = copy.deepcopy(fit)
        self.simulations = simulations
        self.seed = secrets.randbits(32)
        self.cancel_event = threading.Event()
        import uuid
        self.audit = {"event": "montecarlo", "run_id": uuid.uuid4().hex,
                      "dataset_id": fit.record["dataset_id"], "dataset": fit.record["dataset"],
                      "settings": copy.deepcopy(fit.record["settings"]),
                      "selection": [fit.record["selection_start"], fit.record["selection_end"]],
                      "method": "paired_bootstrap_ols_v1", "simulations": simulations,
                      "seed": self.seed, "started_at": utc_now(), "completed": 0}

    def request_stop(self):
        self.cancel_event.set()
        self.requestInterruption()

    def run(self):
        def report(completed, total):
            self.audit["completed"] = completed
            self.progress_changed.emit(int(100 * completed / total),
                                       f"Monte Carlo · {completed}/{total} simulations")
        try:
            fit = montecarlo_result(self.fit, self.simulations, self.seed,
                                    report, self.cancel_event.is_set)
            fit.record["run_id"] = self.audit["run_id"]
            self.audit.update({"status": "completed", "finished_at": utc_now(),
                               "ratio": fit.record["ratio"],
                               "ratio_ci95_lower": fit.record["ratio_ci95_lower"],
                               "ratio_ci95_upper": fit.record["ratio_ci95_upper"],
                               "attempted": fit.record["montecarlo"]["attempted"]})
            self.results_ready.emit(fit, self.audit)
        except InterruptedError:
            self.audit.update({"status": "cancelled", "finished_at": utc_now()})
            self.results_ready.emit(None, self.audit)
        except Exception:
            self.failed.emit(traceback.format_exc())


class SpatialThread(QtCore.QThread):
    progress_changed = QtCore.Signal(int, str)
    results_ready = QtCore.Signal(object, object)
    failed = QtCore.Signal(str)

    def __init__(self, dataset, settings, polygon, selection, parent=None):
        super().__init__(parent)
        self.dataset = copy.deepcopy(dataset)
        self.settings = copy.deepcopy(settings)
        self.polygon = copy.deepcopy(polygon)
        self.selection = selection
        self.cancel_event = threading.Event()
        import uuid
        self.audit = {"event": "spatial_interpolation", "run_id": uuid.uuid4().hex,
                      "dataset_id": dataset.id, "settings": asdict(settings),
                      "polygon": polygon, "started_at": utc_now()}

    def request_stop(self):
        self.cancel_event.set()
        self.requestInterruption()

    def run(self):
        try:
            result = interpolate_spatial(self.dataset, self.settings, self.polygon, self.selection,
                                          self.progress_changed.emit, self.cancel_event.is_set)
            result.metadata["run_id"] = self.audit["run_id"]
            self.audit.update({"status": "completed", "finished_at": utc_now(),
                               "inside_cells": result.metadata["inside_cells"],
                               "estimated_cells": result.metadata["estimated_cells"]})
            self.results_ready.emit(result, self.audit)
        except InterruptedError:
            self.audit.update({"status": "cancelled", "finished_at": utc_now()})
            self.results_ready.emit(None, self.audit)
        except Exception:
            self.failed.emit(traceback.format_exc())


