    def read_settings(self):
        return SpatialSettings(**{key: combo.currentText() for key, combo in self.channels.items()},
            method=self.method.currentData(), cells_x=self.cells_x.value(), cells_y=self.cells_y.value(),
            coordinate_mode=self.coordinate_mode.currentData(), cartesian_reference=self.reference.text().strip(),
            idw_power=self.power.value(), idw_neighbors=self.neighbors.value(), idw_radius=self.radius.value(),
            duplicate_policy=self.duplicates.currentData(), only_selection=self.only_selection.isChecked())

    def snapshot(self):
        if self.dataset is not None:
            self.states[self.dataset.id] = {"settings": asdict(self.read_settings()),
                                           "polygon": copy.deepcopy(self.polygon), "result": self.result}

    def state(self):
        self.snapshot()
        return {"datasets": {key: {"settings": value["settings"], "polygon": value["polygon"],
                                  "result": value["result"].payload() if value["result"] is not None else None}
                             for key, value in self.states.items()}}

    def restore_state(self, state):
        self.dataset = None
        self.result = None
        self.polygon = []
        self.points_cache = None
        self.states = {key: {"settings": value["settings"], "polygon": value.get("polygon", []),
                             "result": SpatialResult.from_payload(value["result"]) if value.get("result") else None}
                       for key, value in state.get("datasets", {}).items()}

    def set_context(self, dataset, selection=None):
        if self.dataset is dataset and dataset is not None:
            changed = self.selection != selection and self.only_selection.isChecked()
            changed = changed or (self.points_cache is not None and self.points_cache[0] != id(dataset.frame))
            self.selection = selection
            if changed:
                self.result = None
                self.points_cache = None
                self.update_controls()
                self.render()
            return
        self.snapshot()
        self.dataset, self.selection = dataset, selection
        self.points_cache = None
        self.updating = True
        columns = list(dataset.frame.columns[1:]) if dataset is not None else []
        saved = self.states.get(dataset.id) if dataset is not None else None
        x = next((name for name in columns if "lon" in name.lower()), columns[0] if columns else "")
        y = next((name for name in columns if "lat" in name.lower()), columns[1] if len(columns) > 1 else "")
        z = next((name for name in columns if "co2" in name.lower()), next((name for name in columns if name not in {x, y}), x))
        default = SpatialSettings(x, y, z, coordinate_mode="wgs84" if "lon" in x.lower() and "lat" in y.lower() else "cartesian")
        settings = SpatialSettings(**saved["settings"]) if saved else default
        for key, combo in self.channels.items():
            combo.clear()
            combo.addItems(columns)
            combo.setCurrentIndex(max(0, combo.findText(getattr(settings, key))))
        for combo, value in ((self.method, settings.method), (self.coordinate_mode, settings.coordinate_mode),
                              (self.duplicates, settings.duplicate_policy)):
            combo.setCurrentIndex(max(0, combo.findData(value)))
        for editor, value in ((self.cells_x, settings.cells_x), (self.cells_y, settings.cells_y),
                               (self.power, settings.idw_power), (self.neighbors, settings.idw_neighbors),
                               (self.radius, settings.idw_radius)):
            editor.setValue(value)
        self.reference.setText(settings.cartesian_reference)
        self.only_selection.setChecked(settings.only_selection)
        self.draw_button.setChecked(False)
        self.polygon = copy.deepcopy(saved["polygon"]) if saved else []
        self.result = saved["result"] if saved else None
        self.updating = False
        if self.result is not None:
            try:
                _, _, source = self.points()
                if (self.result.metadata["source"]["source_signature"] != source["source_signature"] or
                    self.result.metadata["settings"] != asdict(self.read_settings())):
                    self.result = None
            except (AnalysisError, KeyError):
                self.result = None
        self.update_controls()
        self.render()

    def points(self):
        if self.dataset is None:
            raise AnalysisError("Open a dataset first.")
        if self.points_cache is None:
            self.points_cache = (id(self.dataset.frame), prepare_spatial_points(self.dataset, self.read_settings(), self.selection))
        return self.points_cache[1]

    def update_controls(self):
        self.controls.setEnabled(not self.busy and self.dataset is not None)
        self.idw_group.setVisible(self.method.currentData() == "idw")
        self.reference.setEnabled(self.coordinate_mode.currentData() == "cartesian")
        available = not self.busy and self.dataset is not None
        for widget in (self.draw_button, self.hull_button, self.clear_button):
            widget.setEnabled(available)
        self.interpolate_button.setEnabled(available and bool(self.polygon))
        self.export_button.setEnabled(available and self.result is not None)
        self.grid_info.setText(f"{self.cells_x.value():,} × {self.cells_y.value():,} = "
                               f"{self.cells_x.value() * self.cells_y.value():,} cells in the bounding rectangle")
        self.radius.setSuffix(" m" if self.coordinate_mode.currentData() == "wgs84" else " units")

    def parameters_changed(self, key=None):
        if self.updating:
            return
        if key in {"x_channel", "y_channel"}:
            self.polygon = []
        self.result = None
        self.points_cache = None
        self.update_controls()
        self.render()
        self.changed.emit()

    def draw_toggled(self, active):
        if self.updating:
            return
        if active and self.toolbar.mode:
            if self.toolbar.mode.name == "PAN":
                self.toolbar.pan()
            elif self.toolbar.mode.name == "ZOOM":
                self.toolbar.zoom()
        if self.selector is not None:
            self.selector.set_active(active and not self.busy)
        self.canvas.setFocus()

    def use_hull(self):
        try:
            points, _, _ = self.points()
            self.polygon = spatial_hull(points)
            self.result = None
            self.update_controls()
            self.render()
            self.changed.emit()
        except (AnalysisError, ValueError) as error:
            self.error.emit(str(error))

    def clear_polygon(self):
        self.polygon, self.result = [], None
        self.draw_button.setChecked(False)
        self.update_controls()
        self.render()
        self.changed.emit()

    def polygon_selected(self, vertices):
        try:
            self.polygon = validate_polygon(vertices).tolist()
        except (AnalysisError, ValueError) as error:
            message = str(error)
            QtCore.QTimer.singleShot(0, lambda: self.render(message))
            return
        self.result = None
        self.update_controls()
        self.changed.emit()
        QtCore.QTimer.singleShot(0, self.render)

    def render(self, message=None):
        if not self.isVisible():
            return
        if self.selector is not None:
            self.selector.disconnect_events()
            self.selector = None
        if self.colorbar is not None:
            self.colorbar.remove()
            self.colorbar = None
        self.axis.clear()
        try:
            import numpy as np
            points, z, source = self.points()
            settings = self.read_settings()
            data_inside = polygon_contains(points, self.polygon) if self.polygon else np.ones(len(points), bool)
            combined = np.r_[z, self.result.values[np.isfinite(self.result.values)]] if self.result is not None else z
            vmin, vmax = float(combined.min()), float(combined.max())
            mappable = None
            if self.result is not None:
                mappable = self.axis.imshow(np.ma.masked_invalid(self.result.values), origin="upper",
                    extent=self.result.metadata["bounds"], interpolation="nearest", cmap="viridis", vmin=vmin, vmax=vmax)
            shown = np.linspace(0, len(points) - 1, min(len(points), 20000), dtype=int)
            outside = shown[~data_inside[shown]]
            if len(outside):
                self.axis.scatter(points[outside, 0], points[outside, 1], c="#b7c1cb", s=12)
            inside = shown[data_inside[shown]]
            scatter = self.axis.scatter(points[inside, 0], points[inside, 1], c=z[inside], cmap="viridis",
                vmin=vmin, vmax=vmax, s=18, edgecolors="#26354a", linewidths=.35, zorder=3)
            self.colorbar = self.figure.colorbar(mappable if mappable is not None else scatter, ax=self.axis, label=settings.z_channel)
            if self.polygon:
                polygon = np.asarray(self.polygon)
                self.axis.plot(*np.vstack([polygon, polygon[0]]).T, color="#177e69", linewidth=1.5, zorder=4)
            self.axis.set_xlabel(settings.x_channel)
            self.axis.set_ylabel(settings.y_channel)
            self.axis.ticklabel_format(axis="both", useOffset=False)
            aspect = 1 / max(.05, np.cos(np.deg2rad(points[:, 1].mean()))) if settings.coordinate_mode == "wgs84" else 1
            self.axis.set_aspect(aspect, adjustable="datalim")
            self.axis.margins(.08)
            self.axis.set_title("Spatial interpolation" if self.result is None else
                                "IDW interpolation" if settings.method == "idw" else "Cubic interpolation · Clough–Tocher")
            self.axis.grid(alpha=.15)
            self.selector = PolygonSelector(self.axis, self.polygon_selected, useblit=True,
                props={"color": "#177e69", "linewidth": 1.5}, handle_props={"markerfacecolor": "white", "markeredgecolor": "#177e69"})
            if self.polygon:
                self.selector.verts = self.polygon
            self.selector.set_active(self.draw_button.isChecked() and not self.busy)
            text = (f"{source['unique_points']:,} unique locations · {source['invalid_rows']:,} invalid rows excluded · "
                    f"{source['duplicate_rows']:,} duplicate rows aggregated")
            if self.result is not None:
                data = self.result.metadata
                text += (f"\n{data['estimated_cells']:,} estimated / {data['inside_cells']:,} polygon cells "
                         f"({data['grid_cells']:,} rectangular cells) · {data['projection']['working_crs']}")
            else:
                text += "\nDraw a polygon or use Polygon around points, then click Interpolate."
            self.info.setText(message or text)
        except (AnalysisError, ValueError, KeyError) as error:
            self.info.setText(str(error))
            self.axis.set_title("Select valid spatial channels")
        self.canvas.draw_idle()

    def accept_result(self, result):
        self.result = result
        self.update_controls()
        self.render()

    def set_busy(self, busy):
        self.busy = busy
        self.update_controls()
        self.toolbar.setEnabled(not busy)
        if self.selector is not None:
            self.selector.set_active(not busy and self.draw_button.isChecked())

    def export_matrix(self):
        if self.result is None or self.busy:
            return
        path, _ = QtWidgets.QFileDialog.getSaveFileName(self, "Export spatial matrix", "spatial_grid.csv", "CSV (*.csv)",
            options=QtWidgets.QFileDialog.Option.DontUseNativeDialog)
        if not path:
            return
        if not path.lower().endswith(".csv"):
            path += ".csv"
        try:
            csv, metadata = export_spatial(path, self.result)
            self.status.emit(f"Saved {csv.name} and {metadata.name}.")
        except Exception as error:
            self.error.emit(f"Could not export the spatial grid: {error}")


